def _load_data(path):
    """
    Loads data from a directory.
    Returns tuple (config_dict, wordlists).
    Raises Exception on failure (e.g. if data is corrupted).
    """
    config_dict = {}
    wordlists = []
    for filename in os.listdir(path):
        if filename.endswith('.txt'):
            with open(os.path.join(path, filename), 'r') as f:
                wordlists.append(f.read().splitlines())
        else:
            config_dict[filename[:-5]] = json.load(open(os.path.join(path, filename), 'r'))
    return config_dict, wordlists

